import sys; sys.path.insert(0,'.')
from cvlib import folds
d=np.load('base_reads.npz'); y=d['y']; R=np.load('reserved.npy')
keep=np.setdiff1d(np.arange(768),R)
M={j:d[f'mean_hidden_L{j}'][:,keep] for j in range(13)}
def z(X): return (X-X.mean(0))/(X.std(0)+1e-6)
def blk(F): F=F-F.mean(0); return F/np.sqrt((F**2).sum(1).mean())
def pcv(F, y, lams, seeds=(0,1,2)):
    Y=np.eye(8)[y]; out={}
    for lam in lams:
        a=[]
        for s in seeds:
            f=folds(y,5,s); S=np.zeros((len(y),8))
            for i in range(5):
                tr=f!=i; te=f==i
                mu=F[tr].mean(0); Ft=F[tr]-mu
                A=np.linalg.solve(Ft@Ft.T+lam*np.eye(tr.sum()), Y[tr]-Y[tr].mean(0))
                S[te]=(F[te]-mu)@(Ft.T@A)
            a.append((S.argmax(1)==y).mean())
        out[lam]=round(100*np.mean(a),2)
    return out
Z=z(M[8]); Zn=Z/np.linalg.norm(Z,axis=1,keepdims=True)*np.sqrt(760)
L2b=blk(z(M[2])); L6b=blk(z(M[6])); Lt=blk(Zn)
print('lin(8,2,6)', pcv(np.hstack([Lt,L2b,L6b]),y,(0.003,0.01,0.03)))
rng=np.random.RandomState(0)
for a in (0.5,1.0):
    Wr=rng.randn(760,760)/np.sqrt(760); b=rng.randn(760)*1.0
    P=blk(np.tanh(a*(Zn@Wr.T)+b))
    for wP in (1.0,2.0):
        print('rand a',a,'wP',wP, pcv(np.hstack([wP*P,L2b,L6b]),y,(0.003,0.01,0.03)))
        print('   +lin top', pcv(np.hstack([wP*P,Lt,L2b,L6b]),y,(0.003,0.01,0.03)))
